    "konj_det_f1_r3_exp_men": "\"Men\" shpreh kontrast, jo një zgjedhje pyetëse.",
    "konj_det_f1_r3_exp_så": "\"Så\" shpreh një pasojë ose një rezultat.",
    "konj_det_f1_r4_prompt": "Tani \"ikke\" qëndron PAS foljes (\"kan ikke\")! Cila lidhëz shkakore i përshtatet një fjalie kryesore?",
    "konj_det_f1_r4_exp_for": "Plotësisht e saktë! Kur \"ikke\" qëndron PAS foljes (\"jeg kan ikke\"), është fjali kryesore – dhe atëherë përdorim \"for\"!",
    "konj_det_f1_r4_exp_fordi": "\"Fordi\" kërkon rend fjalësh të fjalisë së varur (\"... fordi jeg ikke kan\").",
    "konj_det_f1_r4_exp_så": "\"Så\" shpreh rezultat, jo arsye.",
    "konj_det_f1_r5_prompt": "Shikoni rendin e fjalëve pas presjes: Kryefjala (\"vi\") qëndron PARA foljes (\"bestilte\"). Cila fjalë për rezultat përshtatet?",
    "konj_det_f1_r5_exp_så": "E saktë! Lidhëza \"så\" jep rezultatin në një fjali kryesore pa inversion (\"..., så vi bestilte pizza\").",
    "konj_det_f1_r5_exp_for": "\"For\" tregon arsyen, por pica është rezultati i frigoriferit të zbrazët.",
    "konj_det_f1_r5_exp_derfor": "\"Derfor\" kërkon inversion (folja para kryefjalës: \"... og derfor bestilte vi pizza\").",
