    "konj_det_f1_r6_exp_for": "\"For\" qëndron para arsyes (\"Han tager jakke på, for der er frost udenfor\").",
    "konj_det_f1_r6_exp_eller": "\"Eller\" përdoret vetëm për alternativa.",
    "konj_det_f2_r1_prompt": "Shikoni me kujdes rendin e fjalëve në fjalinë 2: Fjala \"ikke\" qëndron PARA foljes (\"ikke kan\"). Cilën lidhëz shkakore DUHET të zgjedhim?",
    "konj_det_f2_r1_exp_fordi": "Vëzhgim i shkëlqyer! Meqenëse \"ikke\" qëndron PARA foljes (\"jeg ikke kan\"), është fjali e varur – dhe prandaj duhet të përdorim \"fordi\"!",
    "konj_det_f2_r1_exp_for": "\"For\" nis një fjali kryesore, kështu që do të kërkonte \"..., for jeg kan ikke finde...\".",
    "konj_det_f2_r1_exp_så": "\"Så\" shpreh rezultat, jo arsye.",
    "konj_det_f2_r2_prompt": "Shikoni rendin e fjalëve: \"ikke\" qëndron PARA foljes (\"ikke havde\"). Cilën fjalë kontrasti duhet të zgjedhim?",
    "konj_det_f2_r2_exp_selvom": "E përsosur! Si kuptimi (pavarësisht se) ashtu edhe rendi i fjalëve të fjalisë së varur (\"ikke havde\") tregojnë drejtpërdrejt te \"selvom\"!",
    "konj_det_f2_r2_exp_men": "\"Men\" është lidhëz fjalie kryesore dhe do të kërkonte \"..., men han havde ikke øvet sig\".",
    "konj_det_f2_r2_exp_hvis": "\"Hvis\" shpreh një kusht, jo \"pavarësisht se\".",
    "konj_det_f2_r3_prompt": "Fjalia vendos një kusht për të marrë zbritje:",
    "konj_det_f2_r3_exp_Hvis": "Fiks fare! \"Hvis\" shpreh një kusht (\"me kusht që...\").",
    "konj_det_f2_r3_exp_Om": "\"Om\" përdoret vetëm për fjali të varura pyetëse (\"Jeg spurgte, om...\").",
    "konj_det_f2_r3_exp_Selvom": "\"Selvom\" do të thotë \"edhe pse / me gjithë\".",
    "konj_det_f2_r4_prompt": "Mette ka dyshime dhe bën një pyetje të tërthortë po/jo:",
    "konj_det_f2_r4_exp_om": "E saktë! Pas \"Ved du...\" ose \"Jeg ved ikke...\" përdoret gjithmonë \"om\" (\"nëse / a / whether\") për pyetje dhe pasiguri.",
    "konj_det_f2_r4_exp_at": "\"At\" përdoret vetëm kur konstatohet një fakt i sigurt (\"Jeg ved, at bussen er kørt\").",
    "konj_det_f2_r4_exp_hvis": "Në danisht NUK mund të përdoret \"hvis\" pas \"ved ikke\" (ndryshe nga anglishtja \"if\"). Këtu duhet të përdoret \"om\"!",
    "konj_det_f2_r5_prompt": "Çiklisti jep një njoftim të sigurt se ai vjen në orar:",
    "konj_det_f2_r5_exp_at": "Plotësisht e saktë! Kur ritransmetohet një thënie ose dije e sigurt, përdoret \"at\" (+ kryefjalë + \"ikke\" + folje).",
    "konj_det_f2_r5_exp_om": "\"Om\" përdoret për dyshime dhe pyetje.",
    "konj_det_f2_r5_exp_hvis": "\"Hvis\" përdoret për kushte.",
    "konj_det_f2_r6_prompt": "Ekskursioni në plazh varet nga moti i thatë si parakusht:",
    "konj_det_f2_r6_exp_hvis": "Pikërisht! Moti pa shi është kushti për udhëtimin në plazh, dhe \"ikke\" qëndron para foljes (\"ikke regner\").",
