    "konj_det_f2_r6_exp_om": "\"Om\" përdoret për pyetje të tërthorta.",
    "konj_det_f3_r1_prompt": "Po flasim për një ngjarje të caktuar në të shkuarën (vitin e kaluar, kur mbusha 30 vjeç):",
    "konj_det_f3_r1_exp_Da": "Pikërisht! Njeriu mbush 30 vjeç vetëm një herë në të shkuarën – prandaj përdorim \"Da\"!",
    "konj_det_f3_r1_exp_Når": "\"Når\" përdoret vetëm për të tashmen, të ardhmen ose zakone të përsëritura (\"çdo herë\").",
    "konj_det_f3_r1_exp_Mens": "\"Mens\" përdoret për dy veprime që vazhdojnë në të njëjtën kohë.",
    "konj_det_f3_r2_prompt": "Këtu përshkruajmë një zakon fiks, që përsëritet çdo mëngjes:",
