    "konj_det_f3_r3_prompt": "Dy veprime ndodhin saktësisht në të njëjtën kohë:",
    "konj_det_f3_r3_exp_mens": "E saktë! \"Mens\" (\"ndërsa / while\") lidh dy veprime të njëkohshme së bashku.",
    "konj_det_f3_r3_exp_inden": "\"Inden\" do të thotë \"para se / përpara\".",
    "konj_det_f3_r3_exp_siden": "\"Siden\" tregon prapa te një pikënisje në të shkuarën.",
