    "konj_det_f3_r4_exp_efter at": "\"Efter at\" do të thotë më pas / mbasi.",
    "konj_det_f3_r4_exp_mens": "\"Mens\" do të thotë në të njëjtën kohë me.",
    "konj_det_f3_r5_prompt": "Rrimë brenda, fiks deri në momentin kur stuhia të qetësohet:",
    "konj_det_f3_r5_exp_indtil": "E saktë! \"Indtil\" (\"derisa\") shënon pikën përfundimtare të kohëzgjatjes së pritjes sonë.",
    "konj_det_f3_r5_exp_så snart": "\"Så snart\" do të thotë \"në të njëjtin sekondë me\".",
    "konj_det_f3_r5_exp_mens": "\"Mens\" përqendrohet te kohëzgjatja paralele pa një kufi përfundimtar.",
    "konj_det_f3_r6_prompt": "Udhëtari telefonon në shtëpi në të njëjtin sekondë që avioni prek tokën:",
    "konj_det_f3_r6_exp_så snart": "E përsosur! \"Så snart\" (\"sapo / posa\") tregon se telefonata bëhet menjëherë me uljen e avionit.",
