    "konj_det_f3_r6_exp_siden": "\"Siden\" tregon prapa te një pikënisje në të shkuarën.",
    "konj_bld_f1_e1_ctx": "Ndërtoni fjalinë kryesore pas \"Solen skinner,\"",
    "konj_bld_f1_e1_step1": "E saktë! \"Og\" lidh dy fjali kryesore së bashku me rend krejt normal fjalësh (Kryefjalë + Folje).",
    "konj_bld_f1_e1_mode": "Fjali kryesore me \"og\" (Bashkërenditje pa ndryshim të rendit të fjalëve)",
    "konj_bld_f1_e2_ctx": "Ndërtoni fjalinë kryesore me kontrast pas \"Det regner lidt,\" (Mos harroni: në fjalinë kryesore folja qëndron PARA \"ikke\"!)",
    "konj_bld_f1_e2_step1": "Shumë mirë! \"Men\" është lidhëz bashkërenditëse, prandaj folja (\"går\") qëndron PARA \"ikke\"!",
    "konj_bld_f1_e2_mode": "Fjali kryesore me \"men\" (IKKE qëndron PAS foljes!)",
