    "konj_bld_f1_e3_mode": "Fjali kryesore me \"eller\" (Alternativë / zgjedhje)",
    "konj_bld_f1_e4_ctx": "Ndërtoni fjalinë kryesore pas \"Han bliver hjemme,\" me \"for\" (Mos harroni: në fjalinë kryesore folja qëndron PARA \"ikke\"!)",
    "konj_bld_f1_e4_step1": "Shumë mirë! \"For\" është lidhëz fjalie kryesore, kështu që folja (\"er\") vjen PARA \"ikke\"!",
    "konj_bld_f1_e4_mode": "Fjali kryesore me \"for\" (IKKE pas Foljes!)",
