    "konj_bld_f2_e2_mode": "Fjali e varur me \"selvom\" (IKKE para Foljes!)",
    "konj_bld_f2_e3_ctx": "Ndërtoni kushtin pas \"Vi tager på stranden,\"",
    "konj_bld_f2_e3_step1": "E saktë! Pas \"hvis\" jemi në një fjali të varur, kështu që \"ikke\" qëndron para foljes (\"regner\").",
    "konj_bld_f2_e3_mode": "Fjali e varur me \"hvis\" (IKKE para Foljes!)",
    "konj_bld_f2_e4_ctx": "Ndërtoni thënien pas \"Han siger,\" (Mos harroni: \"ikke\" qëndron PARA foljes në fjalinë e varur!)",
    "konj_bld_f2_e4_step1": "Shumë mirë! Pas \"Han siger,\" pason një fjali e varur me \"at\", ku \"ikke\" qëndron para foljes (\"kommer\").",
    "konj_bld_f2_e4_mode": "Fjali e varur pohuese me \"at\" (IKKE para Foljes!)",
    "konj_bld_f2_e5_ctx": "Ndërtoni fjalinë e varur pas \"Hun ved ikke,\" (Dyshim/pyetje)",
    "konj_bld_f2_e5_step1": "Fiks në shenjë! Për dyshime përdorim \"om\", dhe ndajfolja kohore (\"allerede\") qëndron PARA foljes ndihmëse (\"er\") në fjalinë e varur!",
    "konj_bld_f2_e5_mode": "Fjali e varur pyetëse me \"om\" (Ndajfolja para Foljes!)",
    "konj_bld_f3_e1_ctx": "Kur fjalia e varur kohore qëndron në krye (\"Når det regner,\"), FOLJA e fjalisë kryesore duhet të vijë para KRYEFJALËS!",
    "konj_bld_f3_e1_step1": "Shkëlqyeshëm! E gjithë fjalia e varur (\"Når det regner,\") zë Pozicionin 1 (Forfeltet) – kështu që në Pozicionin 2 folja (\"tager\") vjen para kryefjalës (\"jeg\")!",
    "konj_bld_f3_e1_mode": "Modeli A: Fjali e varur me \"Når\" në Forfelt (Inversion në fjalinë kryesore)",
