    "konj_bld_f3_e2_step1": "E saktë! Fëmijëria është një periudhë e përfunduar në të shkuarën (\"Da\"), dhe pas presjes folja (\"boede\") vjen para kryefjalës (\"vi\")!",
    "konj_bld_f3_e2_mode": "Modeli B: Fjali e varur e së shkuarës me \"Da\" në Forfelt (Inversion)",
    "konj_bld_f3_e3_ctx": "Ndërtoni fjalinë e varur kohore pas \"Han hører musik,\"",
    "konj_bld_f3_e3_step1": "E saktë! \"Mens\" lidh dy veprime që ndodhin në të njëjtën kohë.",
    "konj_bld_f3_e3_mode": "Modeli C: Njëkohësi me \"mens\"",
    "konj_bld_f3_e4_ctx": "Ndërtoni fjalinë e varur kohore pas \"Husk at låse døren,\"",
    "konj_bld_f3_e4_step1": "Shumë mirë! \"Inden\" tregon se dera duhet të mbyllet para se të dilni nga shtëpia.",
    "konj_bld_f3_e4_mode": "Modeli D: Renditje me \"inden\" (Para se)",
    "konj_bld_f3_e5_ctx": "Ndërtoni fjalinë e varur kohore pas \"Vi venter under taget,\"",
    "konj_bld_f3_e5_step1": "Pikërisht! \"Indtil\" shënon pikën e përfundimit të kohës së pritjes.",
    "konj_bld_f3_e5_mode": "Modeli E: Pikë përfundimtare në kohë me \"indtil\"",
    "konj_ctx_f1_q1_exp": "\"Og\" shton informacion dhe lidh dy fjali kryesore të barasvlershme së bashku.",
    "konj_ctx_f1_q2_exp": "\"Men\" krijon një kontrast mes shiut dhe faktit që kemi çadër me vete.",
    "konj_ctx_f1_q3_exp": "\"Eller\" jep një zgjedhje mes dy alternativave.",
    "konj_ctx_f1_q4_exp": "Rendi i fjalëve është \"jeg har ikke\" (ikke qëndron PAS foljes) → prandaj është lidhëza e fjalisë kryesore \"for\"!",
    "konj_ctx_f1_q5_exp": "\"Så\" tregon rezultatin në një fjali kryesore pa inversion (\"..., så jeg kom...\").",
    "konj_ctx_f1_q6_exp": "\"For\" jep shpjegimin/arsyen në një fjali kryesore (\"han er slet ikke rask\").",
    "konj_ctx_f1_q7_exp": "\"Så\" prezanton pasojën (\"jeg tager bussen\") pa inversion.",
    "konj_ctx_f1_q8_exp": "\"Men\" shënon kontrastin mes këmbëve të lodhura dhe përfundimit të vrapimit.",
    "konj_ctx_f2_q1_exp": "Rendi i fjalëve është \"radiatoren ikke virker\" (ikke qëndron PARA foljes) → prandaj është lidhëza nënrenditëse \"fordi\"!",
    "konj_ctx_f2_q2_exp": "\"Selvom\" shpreh që ndeshja u luajt pavarësisht shiut.",
    "konj_ctx_f2_q3_exp": "\"Hvis\" vendos kushtin për ekskursionin (dhe ka \"ikke\" para foljes: \"hvis det ikke blæser\").",
